@ Some portions generated by Claude Code (Opus 5).

@ zx_trap_handler.S -- Cortex-R52 -- the ZoneX EL2 exception vectors, and the
@                      launch and recapture of an EL1 payload.
@
@ DESCRIPTION
@
@   The EL2 vector table installed in HVBAR, the trap entry it points at, and
@   the pair of routines that hand the machine to EL1 and take it back.
@
@   Every exception routed to EL2 from EL0 or EL1 arrives at ONE vector,
@   HVBAR + 0x14, so this file's first job is to decode HSR.EC.  A fault
@   taken FROM Hyp mode is different: it arrives at its own vector, +0x0C or
@   +0x10, which makes the vector an INDEPENDENT witness to what HSR claims.
@   Both are captured, and core/src/zx_fault.c reports it when they disagree.
@
@     0x12  HVC executed -- the hypercall seam
@     0x24  data abort ROUTED to Hyp -- a guest violating its partition,
@           with the faulting address in HPFAR.  This is the event the
@           Phase-0 demonstrator exists to show.
@     0x25  data abort TAKEN FROM Hyp -- a ZoneX bug, and it must be
@           reported differently rather than folded in with 0x24.
@
@   The full table is in docs/armv8r-el2-reference.md.
@
@ HOW CONTROL COMES BACK TO EL2
@
@   zx_el2_run_payload saves EL2's own SP, LR and callee-saved registers,
@   then ERETs to EL1.  It does not return through that ERET.  Instead the
@   trap handler restores that context and resumes it with a result code in
@   r0, so from C the whole excursion looks like an ordinary call that
@   returns ZX_RUN_YIELDED, ZX_RUN_FAULTED or ZX_RUN_TRAPPED.
@
@   That shape is deliberate and it is not just convenience for a test.  A
@   handler that decides policy in the vector has no context to decide it
@   with; a hypervisor that gets its faults back as VALUES can choose what to
@   do about a partition -- report it, restart it, stop scheduling it -- in
@   code that can be read.  Step 3 keeps this seam.
@
@   The exception is a fault taken FROM Hyp mode.  There is nothing safe to
@   resume there: ZoneX faulted on its own access, so whatever invariant the
@   resume context assumed may already be false.  Those vectors capture and
@   go to C to report and stop.
@
@ STACK DISCIPLINE
@
@   The Hyp stack is restored wholesale by the resume path, but every push on
@   every path is still balanced explicitly.  Not doing so at EL1 cost a
@   silicon run and leaked bytes of a 1 KB abort stack per fault during the
@   Cortex-R52 Modules port work; a leak that only shows up on the tenth
@   fault is not a leak anybody finds on the bench.
@
@ NOTE ON SYNTAX
@
@   GNU assembler syntax, per CONTRIBUTING.md.

#include "zx_port.h"

    .syntax unified
    .arm

/**************************************************************************/
/*  ZX_CAPTURE -- fill the fault record, before anything else runs.        */
/*                                                                        */
/*  Clobbers r0 and r1.  Every path that uses it has already finished with */
/*  the guest's r0/r1, except the HVC #0 path, which does not use it.      */
/*                                                                        */
/*  The offsets come from zx_port.h and are checked against offsetof by    */
/*  _Static_assert in zx_stage2_mpu.c, so a field added to                 */
/*  zx_fault_record_t breaks the build rather than the report.             */
/**************************************************************************/

    .macro  ZX_CAPTURE vector_offset
    ldr     r0, =zx_el2_fault_storage
    mov     r1, #\vector_offset
    str     r1, [r0, #ZX_ASM_FAULT_OFF_VECTOR]
    mrc     p15, 4, r1, c5, c2, 0               @ HSR
    str     r1, [r0, #ZX_ASM_FAULT_OFF_HSR]
    mrc     p15, 4, r1, c6, c0, 4               @ HPFAR
    str     r1, [r0, #ZX_ASM_FAULT_OFF_HPFAR]
    mrc     p15, 4, r1, c6, c0, 0               @ HDFAR
    str     r1, [r0, #ZX_ASM_FAULT_OFF_HDFAR]
    mrc     p15, 4, r1, c6, c0, 2               @ HIFAR
    str     r1, [r0, #ZX_ASM_FAULT_OFF_HIFAR]
    mrs     r1, ELR_hyp
    str     r1, [r0, #ZX_ASM_FAULT_OFF_ELR]
    mrs     r1, SPSR_hyp
    str     r1, [r0, #ZX_ASM_FAULT_OFF_SPSR]
    ldr     r1, [r0, #ZX_ASM_FAULT_OFF_CAPTURES]
    add     r1, r1, #1
    str     r1, [r0, #ZX_ASM_FAULT_OFF_CAPTURES]
    dsb
    .endm

/**************************************************************************/
/*  The EL2 vector table.  32-byte aligned, as HVBAR requires.            */
/*                                                                        */
/*  Offsets 0x00-0x10 are exceptions taken FROM Hyp mode itself.  Offset   */
/*  0x14 is the Hyp Trap Entry: every exception routed to EL2 from EL1 or  */
/*  EL0 funnels through it.  0x18 and 0x1C are unexpected here, because    */
/*  HCR.IMO and HCR.FMO are clear and interrupts belong to EL1.            */
/**************************************************************************/

    .section .vectors_el2, "ax"
    .balign 32
    .global zx_el2_vectors
zx_el2_vectors:
    b       zx_el2_vector_reset             /* 0x00  reset, unused at EL2  */
    b       zx_el2_vector_undef             /* 0x04  undef, from Hyp       */
    b       zx_el2_vector_svc               /* 0x08  SVC, from Hyp         */
    b       zx_el2_vector_pabt              /* 0x0C  prefetch abort, Hyp   */
    b       zx_el2_vector_dabt              /* 0x10  data abort, from Hyp  */
    b       zx_el2_hyp_trap_entry           /* 0x14  from EL1/EL0          */
    b       zx_el2_vector_irq               /* 0x18  IRQ                   */
    b       zx_el2_vector_fiq               /* 0x1C  FIQ                   */

    .text
    .balign 4

/**************************************************************************/
/*  zx_el2_hyp_trap_entry -- HVBAR + 0x14.                                */
/*                                                                        */
/*  uint32_t is what the caller eventually sees; what arrives here is an   */
/*  exception with its cause only in HSR.                                  */
/**************************************************************************/

    .global zx_el2_hyp_trap_entry
    .type   zx_el2_hyp_trap_entry, %function
zx_el2_hyp_trap_entry:

    @ The guest's r0 and r1 are saved because the HVC #0 path below returns
    @ to it transparently and must not have changed anything.  Every other
    @ path discards them, explicitly, before it goes on.

    push    {r0, r1}

    mrc     p15, 4, r0, c5, c2, 0               @ HSR
    lsr     r1, r0, #ZX_ASM_EC_SHIFT
    cmp     r1, #ZX_ASM_EC_HVC
    bne     zx_el2_trap_not_hypercall

    @ An HVC.  Which one is in HSR.ISS[15:0], and the two ZoneX uses mean
    @ opposite things: #0 is the empty Phase-0 hypercall vector and returns
    @ to the guest, #1 is a payload handing EL2 the machine back.

    ubfx    r1, r0, #0, #16
    cmp     r1, #ZX_ASM_HVC_IMM_NOP
    bne     zx_el2_trap_hvc_not_nop

    ldr     r0, =zx_el2_hypercall_counter
    ldr     r1, [r0]
    add     r1, r1, #1
    str     r1, [r0]
    dsb
    pop     {r0, r1}                            @ balanced with the push
    eret

zx_el2_trap_hvc_not_nop:
    cmp     r1, #ZX_ASM_HVC_IMM_YIELD
    bne     zx_el2_trap_not_hypercall

    @ HVC #1.  The record is captured for a yield as well as for a fault:
    @ "the payload came back" is evidence too, and a run that can only
    @ report the absence of a fault cannot tell a working protection
    @ failure from a broken test.

    add     sp, sp, #8                          @ done with the guest's r0/r1
    ZX_CAPTURE ZX_ASM_VEC_HYP_TRAP
    mov     r0, #ZX_RUN_YIELDED
    b       zx_el2_resume

zx_el2_trap_not_hypercall:
    add     sp, sp, #8                          @ done with the guest's r0/r1
    ZX_CAPTURE ZX_ASM_VEC_HYP_TRAP

    @ Re-read EC from the record's own copy rather than from a register
    @ that survived the capture, so that what is dispatched on is exactly
    @ what will be reported.

    ldr     r0, =zx_el2_fault_storage
    ldr     r1, [r0, #ZX_ASM_FAULT_OFF_HSR]
    lsr     r1, r1, #ZX_ASM_EC_SHIFT

    cmp     r1, #ZX_ASM_EC_DABT_ROUTED
    beq     zx_el2_trap_guest_violation
    cmp     r1, #ZX_ASM_EC_PABT_ROUTED
    beq     zx_el2_trap_guest_violation

    mov     r0, #ZX_RUN_TRAPPED
    b       zx_el2_resume

zx_el2_trap_guest_violation:
    mov     r0, #ZX_RUN_FAULTED
    b       zx_el2_resume
    .size   zx_el2_hyp_trap_entry, . - zx_el2_hyp_trap_entry

/**************************************************************************/
/*  zx_el2_run_payload -- drop to EL1 and come back.                      */
/*                                                                        */
/*    uint32_t zx_el2_run_payload(zx_addr_t entry_address,                 */
/*                                uint32_t argument);                     */
/*                                                                        */
/*  r0 = entry address, r1 = argument passed to the payload in r0.         */
/*                                                                        */
/*  Interrupts are masked in the payload's SPSR (A, I and F all set).      */
/*  Phase 0 configures no interrupt controller and routes nothing to EL2,  */
/*  so an interrupt arriving while a payload runs would be taken by EL1    */
/*  with no handler behind it.  Masking says that out loud rather than     */
/*  leaving it to luck; step 4 opens them when a guest has vectors.        */
/**************************************************************************/

    .global zx_el2_run_payload
    .type   zx_el2_run_payload, %function
zx_el2_run_payload:
    ldr     r2, =zx_el2_resume_context
    str     sp, [r2, #ZX_ASM_RESUME_OFF_SP]
    str     lr, [r2, #ZX_ASM_RESUME_OFF_LR]
    add     r3, r2, #ZX_ASM_RESUME_OFF_R4
    stmia   r3, {r4-r11}

    @ ELR_hyp is set from r0 BEFORE r0 is reused, and SPSR_hyp from a
    @ literal.  The payload's argument then moves into r0 last, so it is
    @ the value the payload sees.

    msr     ELR_hyp, r0
    ldr     r0, =(ZX_PSR_A | ZX_PSR_I | ZX_PSR_F | ZX_MODE_SVC)
    msr     SPSR_hyp, r0
    mov     r0, r1

    dsb
    isb
    eret
    .size   zx_el2_run_payload, . - zx_el2_run_payload

/**************************************************************************/
/*  zx_el2_resume -- restore the context zx_el2_run_payload saved.        */
/*                                                                        */
/*  r0 already holds the ZX_RUN_* result, which becomes                    */
/*  zx_el2_run_payload's return value.  Not called: branched to, from the  */
/*  trap handler, because there is no frame to return through.             */
/**************************************************************************/

    .type   zx_el2_resume, %function
zx_el2_resume:
    ldr     r2, =zx_el2_resume_context
    ldr     sp, [r2, #ZX_ASM_RESUME_OFF_SP]
    ldr     lr, [r2, #ZX_ASM_RESUME_OFF_LR]
    add     r3, r2, #ZX_ASM_RESUME_OFF_R4
    ldmia   r3, {r4-r11}
    isb
    bx      lr
    .size   zx_el2_resume, . - zx_el2_resume

/**************************************************************************/
/*  Vectors for exceptions taken FROM Hyp mode.                           */
/*                                                                        */
/*  These mean ZoneX faulted on its own access, so nothing here tries to   */
/*  resume: the capture happens and C reports and stops.  The distinction  */
/*  from a guest violation is the whole point -- a hypervisor bug reported */
/*  as a partition overstepping is a Phase-0 run that "passes" while       */
/*  proving nothing.                                                       */
/*                                                                        */
/*  Each vector records its OWN offset, which is what lets zx_fault_report */
/*  cross-check the vector against HSR.EC instead of trusting one of them. */
/**************************************************************************/

    .type   zx_el2_vector_pabt, %function
zx_el2_vector_pabt:
    ZX_CAPTURE ZX_ASM_VEC_PABT_HYP
    bl      zx_el2_hypervisor_fault
    .size   zx_el2_vector_pabt, . - zx_el2_vector_pabt

    .type   zx_el2_vector_dabt, %function
zx_el2_vector_dabt:
    ZX_CAPTURE ZX_ASM_VEC_DABT_HYP
    bl      zx_el2_hypervisor_fault
    .size   zx_el2_vector_dabt, . - zx_el2_vector_dabt

/**************************************************************************/
/*  Vectors nothing should reach.                                         */
/*                                                                        */
/*  Reset is unreachable once running; SVC and undefined instruction from  */
/*  Hyp mode mean ZoneX executed something it should not have; IRQ and FIQ */
/*  at EL2 mean HCR.IMO or HCR.FMO is set when this file says they are     */
/*  clear.  All four report by name and stop, because a vector that falls  */
/*  through is how a fault becomes a hang.                                 */
/**************************************************************************/

    .type   zx_el2_vector_reset, %function
zx_el2_vector_reset:
    ZX_CAPTURE ZX_ASM_VEC_RESET
    bl      zx_el2_unexpected_vector
    .size   zx_el2_vector_reset, . - zx_el2_vector_reset

    .type   zx_el2_vector_undef, %function
zx_el2_vector_undef:
    ZX_CAPTURE ZX_ASM_VEC_UNDEF
    bl      zx_el2_unexpected_vector
    .size   zx_el2_vector_undef, . - zx_el2_vector_undef

    .type   zx_el2_vector_svc, %function
zx_el2_vector_svc:
    ZX_CAPTURE ZX_ASM_VEC_SVC
    bl      zx_el2_unexpected_vector
    .size   zx_el2_vector_svc, . - zx_el2_vector_svc

    .type   zx_el2_vector_irq, %function
zx_el2_vector_irq:
    ZX_CAPTURE ZX_ASM_VEC_IRQ
    bl      zx_el2_unexpected_vector
    .size   zx_el2_vector_irq, . - zx_el2_vector_irq

    .type   zx_el2_vector_fiq, %function
zx_el2_vector_fiq:
    ZX_CAPTURE ZX_ASM_VEC_FIQ
    bl      zx_el2_unexpected_vector
    .size   zx_el2_vector_fiq, . - zx_el2_vector_fiq

/**************************************************************************/
/*  The saved EL2 context.  In .bss, so the reset path zeroes it before    */
/*  anything can read it, and read only by the two routines above.         */
/*                                                                        */
/*  ONE slot, so zx_el2_run_payload CANNOT NEST.  That is a real           */
/*  constraint and it is deliberate: a hypervisor that could be inside two */
/*  guest excursions at once would need a stack of these, and Phase 0 has  */
/*  no reason to be.  A time-partition scheduler calls it once per         */
/*  partition, sequentially, and still does not nest.  If a later phase    */
/*  needs to -- an emulated instruction that itself re-enters a guest --   */
/*  this becomes an array indexed by depth, and the depth needs a bound.   */
/**************************************************************************/

    .section .bss
    .balign 8
    .type   zx_el2_resume_context, %object
zx_el2_resume_context:
    .space  ZX_ASM_RESUME_WORDS * 4
    .size   zx_el2_resume_context, . - zx_el2_resume_context
